void MissionPlanner::on_set_preferred_primitive(
  const autoware_planning_msgs::srv::SetPreferredPrimitive::Request::SharedPtr req,
  const autoware_planning_msgs::srv::SetPreferredPrimitive::Response::SharedPtr res)
{
  using ResponseCode = autoware_adapi_v1_msgs::msg::ResponseStatus;
  const auto is_reroute = state_.state == RouteState::SET;

  if (!current_route_) {
    res->status.success = false;
    throw service_utils::ServiceException(
      ResponseCode::NO_EFFECT, "The route has not been set yet.", true);
  }
  if (req->preferred_primitives.size() != current_route_->segments.size() && req->reset == false) {
    res->status.success = false;
    throw service_utils::ServiceException(
      autoware_adapi_v1_msgs::srv::SetRoute::Response::ERROR_INVALID_STATE,
      fmt::format(
        "The size of preferred_primitives ({}) is different from that of the current route ({}).",
        req->preferred_primitives.size(), current_route_->segments.size()));
  }
  if (req->uuid != current_route_->uuid) {
    res->status.success = false;
    throw service_utils::ServiceException(
      autoware_adapi_v1_msgs::srv::SetRoute::Response::ERROR_INVALID_STATE,
      "Route UUID does not match the current route.");
  }

  if (!req->reset && !original_route_) {
    RCLCPP_INFO(get_logger(), "Saved the original route for future resets.");
    original_route_ = std::make_shared<LaneletRoute>(*current_route_);
  }

  if (req->reset && !original_route_) {
    res->status.success = false;
    throw service_utils::ServiceException(
      autoware_adapi_v1_msgs::srv::SetRoute::Response::ERROR_INVALID_STATE,
      "There is no saved original route to reset to.");
  }

  const bool is_autonomous_driving =
    operation_mode_state_ ? operation_mode_state_->mode == OperationModeState::AUTONOMOUS &&
                              operation_mode_state_->is_autoware_control_enabled
                          : false;

  if (is_reroute && is_autonomous_driving) {
    const auto reroute_availability = sub_reroute_availability_.take_data();
    if (!reroute_availability || !reroute_availability->availability) {
      throw service_utils::ServiceException(
        autoware_adapi_v1_msgs::srv::SetRoute::Response::ERROR_INVALID_STATE,
        "Cannot reroute as the planner is not in lane following.");
    }
  }

  if (req->reset) {
    RCLCPP_INFO(get_logger(), "Cleared the saved original route after reset.");

    change_route(**original_route_);
    res->status.message = "Successfully set preferred primitive.";
    res->status.success = true;

    original_route_ = std::nullopt;

    return;
  }

  LaneletRoute current_route = *current_route_;

  for (size_t i = 0; i < current_route.segments.size(); ++i) {
    auto & segment = current_route.segments.at(i);
    const auto & preferred_primitive = req->preferred_primitives.at(i);

    if (std::none_of(
          segment.primitives.begin(), segment.primitives.end(),
          [&preferred_primitive](const autoware_planning_msgs::msg::LaneletPrimitive & p) {
            return p.id == preferred_primitive.id;
          })) {
      res->status.success = false;
      throw service_utils::ServiceException(
        autoware_adapi_v1_msgs::srv::SetRoute::Response::ERROR_INVALID_STATE,
        fmt::format(
          "The preferred_primitive at index {} does not belong to the lanelet segment.", i));
    }

    segment.preferred_primitive = preferred_primitive;
  }

  change_route(current_route);
  res->status.message = "Successfully set preferred primitive.";
  res->status.success = true;
}

void MissionPlanner::change_route(const LaneletRoute & route)
{
  PoseWithUuidStamped goal;
  goal.header = route.header;
  goal.pose = route.goal_pose;
  goal.uuid = route.uuid;

  current_route_ = std::make_shared<LaneletRoute>(route);
  planner_->updateRoute(route);
  arrival_checker_.set_goal(goal);

  pub_route_->publish(route);
  pub_marker_->publish(planner_->visualize(route, goal_lanelet_transparency_));
}

void DefaultPlanner::updateRoute(const PlannerPlugin::LaneletRoute & route)
{
  route_handler_.setRoute(route);
}

void RouteHandler::setRoute(const LaneletRoute & route_msg)
{
  if (!isRouteLooped(route_msg.segments)) {
    // if get not modified route but new route, reset original start pose
    if (!route_ptr_ || route_ptr_->uuid != route_msg.uuid) {
      original_start_pose_ = route_msg.start_pose;
      original_goal_pose_ = route_msg.goal_pose;
    }
    route_ptr_ = std::make_shared<LaneletRoute>(route_msg);
    is_handler_ready_ = false;
    setLaneletsFromRouteMsg();
  } else {
    RCLCPP_ERROR(
      logger_,
      "Loop detected within route! Currently, no loop is allowed for route! Using previous route");
  }
}

bool RouteHandler::isRouteLooped(const RouteSections & route_sections)
{
  std::set<lanelet::Id> lane_primitives;
  for (const auto & route_section : route_sections) {
    for (const auto & primitive : route_section.primitives) {
      if (lane_primitives.find(primitive.id) != lane_primitives.end()) {
        return true;  // find duplicated id
      }
      lane_primitives.emplace(primitive.id);
    }
  }
  return false;
}

void RouteHandler::setLaneletsFromRouteMsg()
{
  if (!route_ptr_ || !is_map_msg_ready_) {
    return;
  }
  route_lanelets_.clear();
  route_lanelets_rtree_.clear();
  preferred_lanelets_.clear();
  const bool is_route_valid = lanelet::utils::route::isRouteValid(*route_ptr_, lanelet_map_ptr_);
  if (!is_route_valid) {
    return;
  }

  size_t primitive_size{0};
  for (const auto & route_section : route_ptr_->segments) {
    primitive_size += route_section.primitives.size();
  }
  route_lanelets_.reserve(primitive_size);
  std::vector<RouteRtreeNode> rtree_nodes;
  rtree_nodes.reserve(primitive_size);
  size_t i = 0;

  for (const auto & route_section : route_ptr_->segments) {
    for (const auto & primitive : route_section.primitives) {
      const auto id = primitive.id;
      const auto & llt = lanelet_map_ptr_->laneletLayer.get(id);
      route_lanelets_.push_back(llt);
      rtree_nodes.emplace_back(
        boost::geometry::return_envelope<autoware_utils_geometry::Box2d>(
          llt.polygon2d().basicPolygon()),
        i++);
      if (id == route_section.preferred_primitive.id) {
        preferred_lanelets_.push_back(llt);
      }
    }
  }
  route_lanelets_rtree_ = RouteRtree(rtree_nodes);
  goal_lanelets_.clear();
  start_lanelets_.clear();
  if (!route_ptr_->segments.empty()) {
    goal_lanelets_.reserve(route_ptr_->segments.back().primitives.size());
    for (const auto & primitive : route_ptr_->segments.back().primitives) {
      const auto id = primitive.id;
      const auto & llt = lanelet_map_ptr_->laneletLayer.get(id);
      goal_lanelets_.push_back(llt);
    }
    start_lanelets_.reserve(route_ptr_->segments.front().primitives.size());
    for (const auto & primitive : route_ptr_->segments.front().primitives) {
      const auto id = primitive.id;
      const auto & llt = lanelet_map_ptr_->laneletLayer.get(id);
      start_lanelets_.push_back(llt);
    }
  }
  is_handler_ready_ = true;
}

bool route::isRouteValid(
  const LaneletRoute & route_msg, const lanelet::LaneletMapPtr lanelet_map_ptr_, bool allow_area)
{
  for (const auto & route_section : route_msg.segments) {
    for (const auto & primitive : route_section.primitives) {
      // If area is not allowed, and the primitive is an area, return false
      if (primitive.primitive_type == "area" && !allow_area) {
        return false;
      }
      const auto id = primitive.id;
      try {
        if (primitive.primitive_type == "area") {
          lanelet_map_ptr_->areaLayer.get(id);
        } else {
          lanelet_map_ptr_->laneletLayer.get(id);
        }
      } catch (const std::exception & e) {
        std::cerr
          << e.what()
          << ". Maybe the loaded route was created on a different Map from the current one. "
             "Try to load the other Route again."
          << std::endl;
        return false;
      }
    }
  }
  return true;
}

